-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("waybar")
    hl.exec_cmd("swaync")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("hypridle")
    -- nwg-dock requires $SWAYSOCK (Sway IPC) and crashes under Hyprland.
    -- Install nwg-dock-hyprland instead to use a dock.
    -- hl.exec_cmd("nwg-dock -d -i 46 -mb 8 -c 'rofi -show drun' -nows -s style.css")
    -- nm-applet back for the tray WiFi dropdown (user preference);
    -- blueman stays retired (wayland click = window), bluetooth is the custom module.
    hl.exec_cmd("nm-applet --indicator")
    -- keeps the swaync control-center Bluetooth label (disabled/enabled) in
    -- sync with the real rfkill/power/connected state every 5s
    hl.exec_cmd("~/.config/hypr/scripts/bt_sync.sh")
    hl.exec_cmd("/usr/lib/x86_64-linux-gnu/libexec/polkit-kde-authentication-agent-1")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    -- Prune clipboard history entries older than 7 days at startup
    hl.exec_cmd("find /home/dreamer/.cache/cliphist -type f -mtime +7 -delete")
end)
